from typing import List

class Solution:
    def smallestRangeII(self, nums: List[int], k: int) -> int:
        nums.sort()
        ans = nums[-1] - nums[0]
        for i in range(len(nums) - 1):
            hi = max(nums[-1] - k, nums[i] + k)
            lo = min(nums[0] + k, nums[i + 1] - k)
            ans = min(ans, hi - lo)
        return ans

class Solution {
public:
    int smallestRangeII(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        int ans = nums.back() - nums.front();
        for (int i = 0; i < n - 1; i++) {
            int hi = max(nums.back() - k, nums[i] + k);
            int lo = min(nums.front() + k, nums[i + 1] - k);
            ans = min(ans, hi - lo);
        }
        return ans;
    }
